// Traduce un bloque del juego al material acústico correspondiente.
inline Audio::StepMaterial blockToStepMaterial(BlockType b) {
    switch (b) {
        case BLOCK_STONE:
        case BLOCK_COBBLESTONE:
        case BLOCK_BEDROCK:
        case BLOCK_BRICKS:
        case BLOCK_COAL_ORE:
        case BLOCK_IRON_ORE:
        case BLOCK_GOLD_ORE:
        case BLOCK_SILVER_ORE:
        case BLOCK_DIAMOND_ORE:
        case BLOCK_SCRAP_METAL:
            return Audio::StepMaterial::Stone;

        case BLOCK_SAND:
        case BLOCK_CLAY_SAND:
            return Audio::StepMaterial::Sand;

        case BLOCK_GRAVEL:
            return Audio::StepMaterial::Gravel;

        case BLOCK_WOOD:
        case BLOCK_PLANKS:
        case BLOCK_PLANKS_ENCINO:
        case BLOCK_PLANKS_OYAMEL:
        case BLOCK_WOOD_ENCINO:
        case BLOCK_WOOD_OYAMEL:
        case BLOCK_RAMA_PINO:
        case BLOCK_RAMA_ENCINO:
        case BLOCK_RAMA_OYAMEL:
            return Audio::StepMaterial::Wood;

        case BLOCK_SNOW:
            return Audio::StepMaterial::Snow;

        case BLOCK_GRASS:
        case BLOCK_DIRT:
        case BLOCK_LEAVES:
        case BLOCK_TALLGRASS:
        default:
            return Audio::StepMaterial::Grass;
    }
}

