    InventorySlot craftingResult;   // ⭐⭐⭐ Slot de resultado del crafteo
    InventorySlot heldSlot;         // ⭐⭐⭐ Item que el jugador tiene en el cursor
    std::vector<ItemEntity> items;
    bool keys[256];
    double lastMouseX;
